-- Specialised MCQ items (mechanical_piping_supervisor): gas-transmission pipelines, PRS/CGS, CP, metering and compressor stations. Sources are named in standard_ref.
-- Added 2026-10-15; approved by owner instruction (no manual review).
insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, item_type, answer_key, explanation_fa, standard_ref, approval_status, active)
select v.job_role, 'TECHNICAL', v.topic, v.difficulty, v.stem_fa, v.options, v.correct_option, v.item_type, v.answer_key, v.explanation_fa, v.standard_ref, 'APPROVED', true
from (values
  ('mechanical_piping_supervisor', 'ایستگاه تقلیل فشار', 2, 'چرا در ایستگاه تقلیل فشار (CGS/TBS) با افت فشار زیاد، گرمکن (Heater) به‌کار می‌رود؟', '["جبران افت دمای ژول-تامسون و تشکیل هیدرات","افزایش دبی گاز عبوری از رگولاتور ایستگاه","کاهش فشار کاری لوله در خروجی ایستگاه","افزایش عدد ویلی و ارزش حرارتی گاز"]'::jsonb, 0, 'SINGLE', null, 'با افت فشار، دمای گاز حدود ۰٫۴ تا ۰٫۵°C به‌ازای هر بار کاهش می‌یابد و ممکن است زیر نقطه تشکیل هیدرات برسد؛ گرمکن این افت را جبران می‌کند.', 'IGS-M-PL / GPSA – اثر ژول-تامسون'),
  ('mechanical_piping_supervisor', 'ایستگاه تقلیل فشار', 2, 'وظیفهٔ رگولاتور مانیتور (Monitor) در آرایش سری با رگولاتور فعال چیست؟', '["اندازه‌گیری دبی گاز ورودی به ایستگاه","کنترل فشار پایین‌دست در خرابی رگولاتور فعال","حذف رطوبت از گاز پیش از رگولاتور","تخلیهٔ فشار اضافی به اتمسفر و فلر"]'::jsonb, 1, 'SINGLE', null, 'رگولاتور مانیتور با تنظیم کمی بالاتر در حالت عادی باز است و در صورت خرابی (باز ماندن) رگولاتور فعال، فشار پایین‌دست را کنترل می‌کند.', 'EN 12186 / IGS-M-PL – ایستگاه‌های تقلیل فشار'),
  ('mechanical_piping_supervisor', 'تجهیزات ایمنی ایستگاه', 2, 'تفاوت اصلی شیر قطع اضطراری (SSV) و شیر اطمینان (PSV) در ایستگاه گاز چیست؟', '["SSV گاز را تخلیه می‌کند و PSV جریان را قطع می‌کند","هر دو فقط برای اندازه‌گیری فشار به‌کار می‌روند","SSV جریان را قطع می‌کند و PSV گاز اضافی را تخلیه می‌کند","SSV فقط در فشار کم و PSV فقط در فشار زیاد کار می‌کند"]'::jsonb, 2, 'SINGLE', null, 'SSV (Slam-shut) با فشار زیاد/کم، ورودی را می‌بندد و دستی ریست می‌شود؛ PSV با باز شدن، گاز را به اتمسفر/فلر تخلیه می‌کند.', 'EN 14382 / API 520-521'),
  ('mechanical_piping_supervisor', 'حفاظت اضافه‌فشار', 3, 'طبق ASME B31.8 برای MAOP ≥ ۶۰ psig، فشار تجهیز محافظ اضافه‌فشار حداکثر به چه مقداری اجازه افزایش می‌دهد؟', '["MAOP به‌علاوهٔ ۵۰٪ در همهٔ شرایط کاری","دو برابر MAOP برای جلوگیری از قطع مکرر","فشار طراحی ایستگاه صرف‌نظر از MAOP خط","MAOP+۱۰٪ یا ۷۵٪ SMYS (هر کدام کمتر)"]'::jsonb, 3, 'SINGLE', null, 'ایستگاه‌های محدودکنندهٔ فشار نباید اجازه دهند فشار از MAOP+۱۰٪ یا فشار متناظر با ۷۵٪ SMYS (کمتر) فراتر رود.', 'ASME B31.8 (Gas Transmission and Distribution Piping Systems)'),
  ('mechanical_piping_supervisor', 'شیرهای قطع خط', 2, 'حداکثر فاصلهٔ شیرهای قطع‌کنندهٔ خط (Sectionalizing valve) در Class 3 طبق ASME B31.8 چقدر است؟', '["حدود ۱۳ کیلومتر (۸ مایل)","حدود ۳۲ کیلومتر (۲۰ مایل)","حدود ۲۴ کیلومتر (۱۵ مایل)","حدود ۶٫۴ کیلومتر (۴ مایل)"]'::jsonb, 0, 'SINGLE', null, 'فاصلهٔ شیرها: Class 1: ۲۰ مایل؛ Class 2: ۱۵؛ Class 3: ۸؛ Class 4: ۴ مایل.', 'ASME B31.8 (Gas Transmission and Distribution Piping Systems)'),
  ('mechanical_piping_supervisor', 'کلاس موقعیت', 3, 'کدام مورد Class 3 را طبق ASME B31.8 تعریف می‌کند؟', '["۱۰ ساختمان یا کمتر در واحد ۱٫۶ کیلومتری","۴۶ ساختمان یا بیشتر در واحد ۱٫۶ کیلومتری","بیش از ۱۰ و کمتر از ۴۶ ساختمان در واحد","ساختمان‌های چهارطبقه یا بیشتر غالب باشند"]'::jsonb, 1, 'SINGLE', null, 'Class 1: ≤ ۱۰ ساختمان؛ Class 2: بین ۱۰ و ۴۶؛ Class 3: ≥ ۴۶ یا فاصله ۱۰۰ یارد از محل تجمع ≥ ۲۰ نفر؛ Class 4: ساختمان‌های ۴ طبقه یا بیشتر غالب.', 'ASME B31.8 (Gas Transmission and Distribution Piping Systems)'),
  ('mechanical_piping_supervisor', 'محاسبه فشار طراحی', 3, 'خط ۴۸ اینچ (قطر خارجی ۱۲۱۹ mm) با ضخامت ۱۹٫۰۵ mm، فولاد X65 (SMYS = 448 MPa)، ضریب طراحی F = 0.72 و E = T = 1 دارد. فشار طراحی طبق B31.8 چند بار است؟', '["","","",""]'::jsonb, 0, 'NUMERIC', '{"unit":"bar","value":100.8,"tolPct":1.5}'::jsonb, 'P = 2·S·t·F·E·T / D = 2×448×19.05×0.72/1219 ≈ 10.08 MPa ≈ 100.8 bar', 'ASME B31.8 – فرمول فشار طراحی'),
  ('mechanical_piping_supervisor', 'تنش محیطی', 2, 'فشار داخلی ۷٫۵ MPa، قطر خارجی ۱۲۱۹ mm و ضخامت ۱۵٫۹ mm است. تنش محیطی (Hoop) تقریباً چند MPa است؟', '["","","",""]'::jsonb, 0, 'NUMERIC', '{"unit":"MPa","value":287.5,"tolPct":2}'::jsonb, 'S = P·D / (2t) = 7.5 × 1219 / (2 × 15.9) ≈ 287.5 MPa', 'ASME B31.8 – تنش محیطی'),
  ('mechanical_piping_supervisor', 'فشار آزمون', 2, 'MOP یک خط در Class 3 برابر ۷۵ بار است. حداقل فشار آزمون هیدرواستاتیک (۱٫۴ × MOP) چند بار است؟', '["","","",""]'::jsonb, 0, 'NUMERIC', '{"unit":"bar","value":105,"tolPct":1}'::jsonb, 'Class 3 و 4: 1.4 × MOP = 1.4 × 75 = 105 bar', 'ASME B31.8 – فشار آزمون'),
  ('mechanical_piping_supervisor', 'اندازه‌گیری گاز', 2, 'نسبت قطر روزنه به قطر لوله (β) در اوریفیس‌متر استاندارد (AGA-3 / ISO 5167-2) در چه محدوده‌ای مجاز است؟', '["۰٫۰۱ ≤ β ≤ ۰٫۰۵ برای اوریفیس لبه‌تیز","۰٫۸ ≤ β ≤ ۰٫۹۵ برای اوریفیس لبه‌تیز","۰٫۱ ≤ β ≤ ۰٫۷۵ برای اوریفیس لبه‌تیز","۱٫۵ ≤ β ≤ ۲٫۰ برای اوریفیس لبه‌تیز"]'::jsonb, 2, 'SINGLE', null, 'محدودهٔ مجاز β برای اوریفیس لبه‌تیز: ۰٫۱ ≤ β ≤ ۰٫۷۵ (در ISO 5167-2).', 'AGA-3 / ISO 5167-2'),
  ('mechanical_piping_supervisor', 'اندازه‌گیری گاز', 2, 'استاندارد AGA-8 برای چه منظوری در اندازه‌گیری گاز به‌کار می‌رود؟', '["تعیین ضخامت صفحه‌ی اوریفیس گاز","کالیبراسیون ترنسمیتر دمای خط","طراحی ابعادی تلهٔ پیگ خط","محاسبهٔ ضریب تراکم‌پذیری گاز طبیعی"]'::jsonb, 3, 'SINGLE', null, 'AGA-8 (و ISO 12213) با ترکیب گاز، فشار و دما ضریب تراکم‌پذیری Z را برای تبدیل حجم به شرایط استاندارد می‌دهد.', 'AGA Report No. 8 / ISO 12213'),
  ('mechanical_piping_supervisor', 'اوریفیس‌متر', 2, 'در اوریفیس‌متر اگر اختلاف فشار (ΔP) چهار برابر شود، دبی تقریباً چند برابر می‌شود؟', '["دو برابر شدن دبی گاز","چهار برابر شدن دبی گاز","نصف شدن دبی گاز","شانزده برابر شدن دبی گاز"]'::jsonb, 0, 'SINGLE', null, 'دبی متناسب با جذر ΔP است؛ ΔP چهار برابر ⇒ دبی دو برابر.', 'AGA-3 / ISO 5167-2'),
  ('mechanical_piping_supervisor', 'اندازه‌گیری گاز', 2, 'نقش صافی‌کننده جریان (Flow conditioner) پیش از اوریفیس یا ترکیب‌شده با مسیر مستقیم چیست؟', '["افزایش افت فشار برای ثبت بهتر دبی","حذف چرخش و اصلاح پروفیل سرعت جریان","حذف رطوبت و ذرات جامد از گاز","افزایش دمای گاز پیش از اندازه‌گیری"]'::jsonb, 1, 'SINGLE', null, 'چرخش و پروفیل نامتقارن خطای اندازه‌گیری ایجاد می‌کند؛ صافی‌کننده این اثر را کم و طول مستقیم را کوتاه می‌کند.', 'AGA-3 / ISO 5167'),
  ('mechanical_piping_supervisor', 'شرایط مبنا', 1, 'شرایط مرجع استاندارد حجم گاز طبیعی طبق ISO 13443 کدام است؟', '["۰°C و ۱۰۰ kPa (شرایط مرجع)","۳۰°C و ۵۰ kPa (شرایط مرجع)","۱۵°C و ۱۰۱٫۳۲۵ kPa (شرایط مرجع)","۲۰°C و ۲۰۰ kPa (شرایط مرجع)"]'::jsonb, 2, 'SINGLE', null, 'ISO 13443: شرایط مرجع ۲۸۸٫۱۵ K و ۱۰۱٫۳۲۵ kPa (اروپا و بسیاری از قراردادهای گاز).', 'ISO 13443'),
  ('mechanical_piping_supervisor', 'ایستگاه تقویت فشار', 2, 'استاندارد API 617 مربوط به کدام نوع کمپرسور است؟', '["کمپرسورهای رفت‌وبرگشتی (Reciprocating)","پمپ‌های آب آتش‌نشانی ساختمان","مخازن ذخیره LPG و پروپان","کمپرسورهای گریز از مرکز (Centrifugal)"]'::jsonb, 3, 'SINGLE', null, 'API 617 کمپرسورهای محوری/گریز از مرکز و API 618 کمپرسورهای رفت‌وبرگشتی را پوشش می‌دهد.', 'API 617 / API 618'),
  ('mechanical_piping_supervisor', 'ایستگاه تقویت فشار', 2, 'پدیدهٔ سرج (Surge) در کمپرسور گریز از مرکز با کدام اقدام کنترل می‌شود؟', '["باز شدن شیر ضدسرج و بازگردانی گاز","بستن کامل شیر ورودی کمپرسور","افزایش دور کمپرسور تا حد ممکن","خاموش کردن سیستم روغن کمپرسور"]'::jsonb, 0, 'SINGLE', null, 'در دبی کم، جریان معکوس و نوسانات شدید رخ می‌دهد؛ شیر ضدسرج گاز را از خروجی به ورودی برمی‌گرداند.', 'API 617'),
  ('mechanical_piping_supervisor', 'نصب تجهیزات دوار', 3, 'حداکثر مقدار مجاز Soft Foot در نصب کمپرسور/ماشین دوار طبق API 686 چقدر است؟', '["حدود ۱ میلی‌متر","حدود ۰٫۰۵ میلی‌متر","حدود ۰٫۵ میلی‌متر","حدود ۵ میلی‌متر"]'::jsonb, 1, 'SINGLE', null, 'API 686: Soft foot نباید از ۰٫۰۵ mm (۰٫۰۰۲ in) بیشتر باشد و تنش لوله (Pipe strain) باید کنترل شود.', 'API 686 (Recommended Practice for Machinery Installation)'),
  ('mechanical_piping_supervisor', 'پیچ و مهره', 2, 'در سفت کردن پیچ‌های فلنج، ترتیب صحیح اعمال گشتاور کدام است؟', '["سفت کردن پیچ‌ها به‌ترتیب دور فلنج یک‌جا","سفت کردن یک نیمه و سپس نیمهٔ دیگر فلنج","ضربدری در چند مرحله و دور نهایی دایره‌ای","شروع از پیچ بالایی و رفتن به پایین فلنج"]'::jsonb, 2, 'SINGLE', null, 'ASME PCC-1: چند مرحله (حدود ۳۰٪، ۶۰٪، ۱۰۰٪) با الگوی ستاره‌ای و یک دور نهایی دایره‌ای.', 'ASME PCC-1'),
  ('mechanical_piping_supervisor', 'آزمون شیر', 3, 'در API 598 فشار آزمون پوسته (Shell) و نشت‌بندی (Seat) هیدرواستاتیک شیر به‌ترتیب چقدر است؟', '["۱٫۱ و ۱٫۵ برابر فشار نامی","۲ و ۲ برابر فشار نامی","۱ و ۱ برابر فشار نامی","۱٫۵ و ۱٫۱ برابر فشار نامی"]'::jsonb, 3, 'SINGLE', null, 'آزمون پوسته ۱٫۵×فشار نامی در ۳۸°C و آزمون نشت‌بندی ۱٫۱×فشار نامی است.', 'API 598 / API 6D'),
  ('mechanical_piping_supervisor', 'مناطق خطرناک', 2, 'طبقه‌بندی Zone 1 طبق IEC 60079-10 چه محیطی را توصیف می‌کند؟', '["گاز قابل اشتعال با احتمال حضور در کار عادی","گاز با حضور مداوم یا طولانی در محیط","گاز با احتمال بسیار کم و کوتاه‌مدت","محیط عاری از گاز قابل اشتعال و بخار"]'::jsonb, 0, 'SINGLE', null, 'Zone 0: مداوم؛ Zone 1: احتمال در کار عادی؛ Zone 2: بعید و کوتاه‌مدت.', 'IEC 60079-10-1'),
  ('mechanical_piping_supervisor', 'ایمنی ایستگاه', 2, 'حد پایین انفجار (LEL) متان و آستانهٔ آلارم پایین تشخیص گاز معمولاً چقدر است؟', '["LEL حدود ۵۰٪ و آلارم پایین ۹۰٪ LEL","LEL حدود ۵٪ حجمی و آلارم پایین ۲۰٪ LEL","LEL حدود ۰٫۵٪ و آلارم پایین ۱۰۰٪ LEL","LEL حدود ۲۰٪ و آلارم پایین ۲۰٪ LEL"]'::jsonb, 1, 'SINGLE', null, 'LEL متان ≈ ۵٪ حجمی؛ آلارم پایین رایج ۲۰٪ LEL و بالا ۴۰ تا ۶۰٪ LEL.', 'IEC 60079-29 / NFPA 69'),
  ('mechanical_piping_supervisor', 'تلهٔ پیگ', 2, 'پیش از باز کردن درب تله پیگ (Pig trap) کدام اقدام الزامی است؟', '["باز کردن آهسته درب برای کنترل نشتی","استفاده از آچار بزرگ برای باز کردن سریع","ایزولاسیون، تخلیه و تأیید فشار صفر با گیج","خنک کردن بدنه با آب روی درب تله"]'::jsonb, 2, 'SINGLE', null, 'باز کردن درب تحت فشار خطر پرتاب درب دارد؛ فشار باید صفر و تأیید شود و اینترلاک فعال باشد.', 'ASME B31.8 / API 6D – Quick opening closure'),
  ('mechanical_piping_supervisor', 'انبساط حرارتی', 2, 'خط لولهٔ فولادی به طول ۱۰۰ متر با ضریب انبساط 12×10⁻⁶ بر درجه سانتی‌گراد، ۵۰ درجه گرم می‌شود. تغییر طول آزاد چند میلی‌متر است؟', '["","","",""]'::jsonb, 0, 'NUMERIC', '{"unit":"mm","value":60,"tolPct":2}'::jsonb, 'ΔL = α·L·ΔT = 12e-6 × 100000 mm × 50 = 60 mm', 'ASME B31.8 – انعطاف‌پذیری')
) as v(job_role, topic, difficulty, stem_fa, options, correct_option, item_type, answer_key, explanation_fa, standard_ref)
